const input = $input.first().json;
const action = input.action || 'listAll';

let params = {};
try {
  params = (typeof input.params === 'string') ? JSON.parse(input.params) : (input.params || {});
} catch (e) {
  params = {};
}

const interval = params.interval_days ? Number(params.interval_days) : null;
let nextRunDate = null;
if (interval) {
  const date = new Date();
  date.setDate(date.getDate() + interval);
  nextRunDate = date.toISOString().split('T')[0];
}

const triggerRaw = params.trigger_percentage;
const trigger = triggerRaw == null || triggerRaw === ''
  ? null
  : (Number(triggerRaw) <= 1 ? Number(triggerRaw) * 100 : Number(triggerRaw));

return [{
  json: {
    action,
    session_id: input.session_id || 'researcher-ui',
    usecase_id: Number(input.usecase_id || params.usecase_id || 0),
    usecase_name: input.usecase_name || params.usecase_name || '',
    schedule_id: params.schedule_id ? Number(params.schedule_id) : null,
    user_id: params.user_id ? Number(params.user_id) : null,
    interval_days: interval,
    next_run_date: nextRunDate,
    trigger_percentage: trigger,
    measure_type: params.measure_type || 'average',
    isValid: action === 'list' || action === 'listAll' || action === 'listActive' ||
      (action === 'add' && params.user_id && params.interval_days) ||
      (action === 'change' && params.schedule_id && params.user_id && params.interval_days) ||
      (action === 'deactivate' && params.schedule_id) ||
      (action === 'activate' && params.schedule_id)
  }
}];

const rows = $input.all().map(i => i.json);
const session_id = $('Execute Workflow Trigger').first().json.session_id;

if (rows.length === 0) {
  return [{ json: { success: false, reply: 'Update failed. Schedule ID not found.', session_id } }];
}

const r = rows[0];
return [{ json: {
  success: true,
  data: [r],
  reply: `Updated schedule ${r.schedule_id}. User: ${r.user_id}, interval: ${r.interval_days} days, measure: ${r.measure_type}, trigger percentage: ${r.trigger_percentage}.`,
  session_id
}}];

const rows = $input.all().map(i => i.json).filter(r => r.schedule_id);
const session_id = $('Execute Workflow Trigger').first().json.session_id;
return [{ json: {
  success: rows.length > 0,
  data: rows,
  reply: rows.length > 0 ? `Schedule ${rows[0].schedule_id} deactivated.` : 'Schedule not found for the selected use case.',
  session_id
}}];

const rows = $input.all().map(i => i.json);
const session_id = $('Execute Workflow Trigger').first().json.session_id;

if (rows.length === 0) {
  return [{ json: { success: false, data: [], reply: 'Schedule was not created.', session_id } }];
}

const r = rows[0];
return [{ json: {
  success: true,
  data: [r],
  reply: `New schedule created with ID ${r.schedule_id} for user ${r.user_id}.`,
  session_id
}}];

const rows = $input.all().map(i => i.json);
const name = $('Execute Workflow Trigger').first().json.usecase_name;
const session_id = $('Execute Workflow Trigger').first().json.session_id;

if (rows.length === 0 || !rows[0].schedule_id) {
  return [{ json: {
    success: true,
    data: [],
    reply: `No schedules found for ${name}.`,
    session_id
  }}];
}

const lines = rows.map(r => {
  let timingInfo = 'N/A';
  if (r.next_run_date) {
    const nextDate = new Date(r.next_run_date);
    const today = new Date();
    const diffTime = nextDate - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    timingInfo = diffDays > 0 ? `in ${diffDays} days` : 'today';
  }
  const activeSuffix = false ? '' : `, Active: ${r.active}`;
  return `ID ${r.schedule_id} - User: ${r.user_id}, Type: ${r.measure_type} (${r.trigger_percentage}%), Next Check: ${timingInfo}, Interval: ${r.interval_days} days${activeSuffix}`;
}).join('\n');

return [{ json: {
  success: true,
  data: rows,
  reply: `All ${name} schedules (${rows.length}):\n${lines}`,
  session_id
}}];

