    const nextDate = new Date(r.next_run_date);
    const today = new Date();
    const diffTime = nextDate - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    timingInfo = diffDays > 0 ? `in ${diffDays} days` : 'today';
  }
  const activeSuffix = true ? '' : `, Active: ${r.active}`;
  return `ID ${r.schedule_id} - User: ${r.user_id}, Type: ${r.measure_type} (${r.trigger_percentage}%), Next Check: ${timingInfo}, Interval: ${r.interval_days} days${activeSuffix}`;
}).join('\n');

return [{ json: {
